import{_ as o,o as e,c as d,ai as r}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"协议观察台","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/protocols.md","filePath":"zh/guide/protocols.md"}'),a={name:"zh/guide/protocols.md"};function n(l,t,s,c,i,h){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="协议观察台" tabindex="-1">协议观察台 <a class="header-anchor" href="#协议观察台" aria-label="Permalink to &quot;协议观察台&quot;">​</a></h1><p><strong>协议观察台</strong>把同一个提示词，通过<strong>三种不同的服务协议</strong>并行发送给你本地的 Ollama 守护进程，并清楚地展示每种协议是如何组织同一段对话的。</p><p><strong>侧边栏位置：</strong> 协议观察台（在代码补全下方） <strong>路由：</strong> <code>/protocols</code><strong>加入版本：</strong> v0.4.7（2026 年 5 月）</p><h2 id="这有什么意义" tabindex="-1">这有什么意义？ <a class="header-anchor" href="#这有什么意义" aria-label="Permalink to &quot;这有什么意义？&quot;">​</a></h2><p>Ollama 并不只说一种协议。它实际上通过三种不同的传输格式暴露同一个本地模型：</p><table tabindex="0"><thead><tr><th>接口</th><th>格式</th><th>流式封装</th></tr></thead><tbody><tr><td><code>/api/chat</code></td><td>Ollama 原生</td><td>NDJSON（每行一个 JSON）</td></tr><tr><td><code>/v1/chat/completions</code></td><td>OpenAI 兼容</td><td>SSE（<code>data: …</code>）</td></tr><tr><td><code>/v1/messages</code></td><td>Anthropic 兼容</td><td>带 <code>event:</code> 标签的 SSE</td></tr></tbody></table><p>不同的生态通过不同的协议与大模型通信。如果你在做集成、调试客户端库，或者只是好奇同一个模型在不同封装下表现如何，这个页面会把差异直观地呈现出来 —— <strong>全部针对同一个本地模型，无云端、无 API key、无需注册。</strong></p><h2 id="使用这个页面" tabindex="-1">使用这个页面 <a class="header-anchor" href="#使用这个页面" aria-label="Permalink to &quot;使用这个页面&quot;">​</a></h2><ol><li>从下拉框选择一个模型。</li><li>输入提示词（已提供默认值）。</li><li>按需调整最大 token 数。</li><li>点击<strong>运行全部 3 种协议</strong>。</li></ol><p>三列会并行流式输出。每一列显示：</p><ul><li><strong>协议名称</strong>与接口路径</li><li>实时<strong>状态标识</strong>（空闲 → 流式中 → 已完成）</li><li><strong>流式回复文本</strong></li><li><strong>指标网格</strong>：TTFT、总耗时、token 数、token/秒、结束原因</li><li>可展开的<strong>报文检查</strong>面板，显示原始的首个与最后一个数据块 / 事件</li></ul><h2 id="报文差异标签页" tabindex="-1">报文差异标签页 <a class="header-anchor" href="#报文差异标签页" aria-label="Permalink to &quot;报文差异标签页&quot;">​</a></h2><p>三次运行全部完成后，下方会出现一个分标签区域。切换到<strong>报文差异</strong>，可以并排比较每种协议如何组织自己的响应：</p><table tabindex="0"><thead><tr><th>方面</th><th>原生</th><th>OpenAI 兼容</th><th>Anthropic 兼容</th></tr></thead><tbody><tr><td>流式封装</td><td>NDJSON</td><td>SSE</td><td>带 <code>event:</code> 标签的 SSE</td></tr><tr><td>结束原因所在字段</td><td><code>done</code> + <code>done_reason</code></td><td><code>choices[].finish_reason</code></td><td><code>message_stop</code> 事件</td></tr><tr><td>token 计数所在字段</td><td><code>eval_count</code> + <code>prompt_eval_count</code></td><td><code>usage.{prompt,completion,total}_tokens</code></td><td><code>usage.{input,output}_tokens</code></td></tr><tr><td>错误报文结构</td><td><code>{&quot;error&quot;: &quot;string&quot;}</code></td><td><code>{&quot;error&quot;: {&quot;message&quot;, &quot;type&quot;, &quot;code&quot;}}</code></td><td><code>{&quot;type&quot;: &quot;error&quot;, &quot;error&quot;: {...}, &quot;request_id&quot;}</code></td></tr></tbody></table><p>标着「本次运行」的行会填入你这次运行中实际观察到的值 —— 于是你可以看到，比如原生协议返回了 <code>done_reason: &quot;stop&quot;</code>，而 Anthropic 协议把同一个结果称为 <code>stop_reason: &quot;end_turn&quot;</code>。</p><h2 id="为什么是三种协议" tabindex="-1">为什么是三种协议？ <a class="header-anchor" href="#为什么是三种协议" aria-label="Permalink to &quot;为什么是三种协议？&quot;">​</a></h2><p>这并非纸上谈兵 —— 很多真实工具都依赖这些兼容层：</p><ul><li><strong>OpenAI 兼容</strong>是 IDE 插件、Cursor、Continue.dev，以及大多数「面向 OpenAI API」的 Python 库与本地模型通信的方式。</li><li><strong>Anthropic 兼容</strong>是 Claude Code、Claude Cowork、OpenClaw 这类工具与 Ollama 通信的方式（Ollama v0.23 / 2026 年 1 月加入）。</li><li><strong>原生</strong>协议给出的指标最丰富 —— 包括各项耗时、评估计数和 <code>done_reason</code> 字段。</li></ul><p>如果某个第三方工具在你的本地 Ollama 上表现异常，协议观察台能让你透过那种协议的视角，看清传输层到底长什么样。</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./chat-diagnostics.html">对话诊断</a>：单一协议下的深入分析</li><li><a href="./compare.html">对比</a>：用同一个提示词比较不同<em>模型</em>（协议观察台则固定模型、变换协议）</li></ul>',21)])])}const g=o(a,[["render",n]]);export{p as __pageData,g as default};
